Tally sweep_c(const Slab& a, const Probe& b, const Gate& c) {
    Tally tally;
    if (!c.read) {
        return tally;
    }
    tally.pages_read = 1;

    const std::size_t count = a.amount_lane.size();
    std::vector<unsigned char> admit(count, 0);
    for (std::size_t i = 0; i < count; ++i) {
        admit[i] = a.presence_lane[i] != 0 ? 1 : 0;
    }

