        bool keep = false;
        switch (b.op) {
            case Op::All:
                keep = true;
                break;
            case Op::Equal:
                keep = a.amount_lane[i] == b.x;
                break;
            case Op::Range:
                keep = a.amount_lane[i] >= b.x && a.amount_lane[i] <= b.y;
